create table if not exists app_sso_provider (id text primary key, issuer text not null, oidc_config text, saml_config text, user_id text references app_user(id) on delete cascade, provider_id text not null unique, organization_id text references app_organization(id) on delete cascade, domain text not null, created_at timestamptz not null default current_timestamp, updated_at timestamptz not null default current_timestamp, constraint app_sso_provider_protocol_check check ((oidc_config is not null)::int + (saml_config is not null)::int = 1));
create unique index if not exists app_sso_provider_domain_idx on app_sso_provider(lower(domain));
